discrete PowerMonitoringSystem
port:
    event input real ReceivePowerData;
    event output real SendAlarm;
state:
    initial state NormalOperation
        when entry() then
            statehold(5);
        end;
        when receive(ReceivePowerData) then
            transition(WarningMode);
        end;
        when receive(ReceivePowerData) then
            transition(NormalOperation);
        end;
    end;

    state WarningMode
        when entry() then
            statehold(5);
        end;
        when receive(ReceivePowerData) then
            transition(NormalOperation);
        end;
        when receive(ReceivePowerData) then
            transition(EmergencyResponse);
        end;
    end;

    state EmergencyResponse
        when entry() then
            statehold(5);
        end;
        when timeover() then
            transition(NormalOperation);
            out
                send(SendAlarm, 1);
        end;
    end;
end;
end;

discrete EnergyManagementSystem
port:
    event input real CollectData;
    event output real OptimizeComplete;
state:
    initial state Evaluation
        when entry() then
            statehold(5);
        end;
        when receive(CollectData) then  // Data collection completed
transition(OptimizationSuggestion);
        end;
    end;

    state OptimizationSuggestion
        when entry() then
            statehold(5);
        end;
        when receive(UserConfirmation) then  // User confirmation of optimisation scheme
transition(ExecuteOptimization);
        end;
    end;

    state ExecuteOptimization
        when entry() then
            statehold(5);
        end;
        when timeover() then  // Implementation of optimization measures completed
transition(Assessment);
        end;
    end;

    state Assessment
        when entry() then
            statehold(5);
        end;
        when timeover() then  // Evaluation completed
transition(Evaluation);
        out
            send(OptimizeComplete, 1);  // Optimizing completion
end;
    end;
end;
end;

discrete DeviceControlSystem
port:
    event input real StartSignal;
    event output real TaskComplete;
state:
    initial state Standby
        when entry() then
            statehold(5);
        end;
        when receive(StartSignal) then  // Received Open signal
transition(Start);
        end;
    end;

    state Start
        when entry() then
            statehold(5);
        end;
        when timeover() then  // Mission started.
transition(Running);
        end;
    end;

    state Running
        when entry() then
            statehold(5);
        end;
        when timeover() then  // Mission accomplished or required to stop.
transition(Stop);
        end;
        when receive(UnsolvableProblem) then  // Unsolved problems
transition(FaultHandling);
        end;
    end;

    state Stop
        when entry() then
            statehold(5);
        end;
        when timeover() then  // Mission accomplished or terminated under external conditions
transition(Standby);
        out
            send(TaskComplete, 1);  // Mission accomplished.
end;
    end;

    state FaultHandling
        when entry() then
            statehold(5);
        end;
        when timeover() then  // We&#x27;re clear.
transition(Standby);
        end;
    end;
end;
end;

couple IndustrialElectricalAutomationSystem
