connection:
    connect(pmsInstance.SendAlarm, emsInstance.CollectData);  // Electricity surveillance system sends alarms to energy management system
connect(emsInstance.OptimizeComplete, dcsInstance.StartSignal);  // Energy management system optimized and equipment control system activated
end;
